sys_variable_value.value:
(function execute(inputs, outputs) {
    outputs.status_code = inputs.status_code;
    if (inputs.status_code != '201') {
        throw new Error('HTTP ' + inputs.status_code + ': ' + inputs.response_body);
    }
    var row = JSON.parse(inputs.response_body).result[0];
    if (row.status == 'error' || row.status == 'ignored') {
        throw new Error('Import ' + row.status + ': ' + row.status_message);
    }
    outputs.remote_sys_id = row.sys_id;          // partner Incident sys_id
    outputs.remote_number = row.display_value;   // partner INC number
    outputs.import_status = row.status;          // inserted or updated
    outputs.partner_system = gs.getProperty('x_1664823_remote_0.partner_system_name');
})(inputs, outputs);

