sys_variable_value.value:
(function execute(inputs, outputs) {
    var map = {
        u_sender_sys_id: inputs.sender_sys_id,
        u_receiver_sys_id: inputs.receiver_sys_id,
        u_sender_number: inputs.sender_number,
        u_sender_system: gs.getProperty('x_1664823_remote_0.local_system_name'),
        u_short_description: inputs.short_description,
        u_description: inputs.description,
        u_caller_email: inputs.caller_email,
        u_impact: inputs.impact,
        u_urgency: inputs.urgency,
        u_category: inputs.category,
        u_subcategory: inputs.subcategory,
        u_business_service: inputs.business_service,
        u_service_offering: inputs.service_offering,
        u_cmdb_ci: inputs.cmdb_ci,
        u_state: inputs.state,
        u_close_code: inputs.close_code,
        u_close_notes: inputs.close_notes,
        u_comments: inputs.comments
    };
    var payload = {};
    for (var key in map) {
        if (map[key]) payload[key] = map[key];   // send only fields that have a value
    }
    outputs.payload = JSON.stringify(payload);   // escapes quotes and new lines safely
    outputs.resource_path = '/api/now/import/' + gs.getProperty('x_1664823_remote_0.partner_staging_table');
})(inputs, outputs);

